<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRoute, useRouter } from "vue-router"; import type { GameDetail } from "@arcade/shared"; import { getPortalGame } from "../services/api"; import { readFavorites, toggleFavorite, rememberRecent } from "../services/portalStorage"; import GameStatusBadge from "../components/portal/GameStatusBadge.vue"; import FavoriteButton from "../components/portal/FavoriteButton.vue"; import LaunchButton from "../components/portal/LaunchButton.vue"; import ContentStatePanel from "../components/portal/ContentStatePanel.vue";
const route = useRoute(); const router = useRouter(); const game = ref<GameDetail | null>(null); const loading = ref(true); const error = ref(""); const favorites = ref<string[]>(readFavorites().values); const slug = String(route.params.slug); async function load(): Promise<void> { try { game.value = await getPortalGame(slug); document.title = `${game.value.title}｜星屿游廊`; } catch { error.value = "找不到这款游戏，或它已从公开目录移除。"; } finally { loading.value = false; } } function favorite(): void { favorites.value = toggleFavorite(slug).values; } function launch(): void { if (!game.value || game.value.status !== "published") return; rememberRecent(slug); void router.push(`/zh/game/${slug}/play`); } onMounted(() => void load());
</script><template><div class="portal-page detail-page"><ContentStatePanel v-if="loading" kind="loading" title="正在打开游戏详情" message="正在核对发布版本和内容信息。" /><ContentStatePanel v-else-if="error" kind="empty" title="游戏不可用" :message="error" action="返回游戏大厅" @action="router.push('/zh/games')" /><template v-else-if="game"><section class="detail-hero" :style="{ '--card-accent': game.accent ?? '#54d6ba' }"><div class="detail-cover"><span>{{ game.legacy_icon || game.title.slice(0, 1) }}</span></div><div class="detail-copy"><GameStatusBadge :status="game.status" /><span class="game-category">{{ game.categories[0]?.name }}</span><h1>{{ game.title }}</h1><p>{{ game.short_description }}</p><div class="detail-actions"><LaunchButton :disabled="game.status !== 'published'" @launch="launch" /><FavoriteButton :active="favorites.includes(slug)" :title="game.title" @toggle="favorite" /></div></div></section><section class="detail-info-grid"><div><span>开发者</span><strong>{{ game.developer_name }}</strong></div><div><span>语言</span><strong>{{ game.supported_locales.join("、") }}</strong></div><div><span>年龄</span><strong>{{ game.age_rating === "all" ? "全年龄" : game.age_rating === "teen" ? "青少年" : "成人" }}</strong></div><div><span>方向</span><strong>{{ game.orientation === "any" ? "不限" : game.orientation === "portrait" ? "竖屏" : "横屏" }}</strong></div><div><span>输入</span><strong>{{ game.input_modes.join("、") }}</strong></div><div><span>更新</span><strong>{{ game.updated_at.slice(0, 10) }}</strong></div></section><section class="detail-text-section"><h2>关于这款游戏</h2><p>{{ game.long_description }}</p><h2>版权与第三方声明</h2><p>{{ game.copyright_notice }}</p><p>{{ game.third_party_notice }}</p><a class="complaint-link" :href="game.complaint_url">发现问题？提交版权或内容投诉</a></section></template></div></template>
